=========== core/ALU.v ===========
     1	`timescale 1ns / 1ps
     2	
     3	module ALU(
     4	    input[31:0] A, B,
     5	    input[3:0] Control,
     6	    output[31:0] res,
     7	    output zero, overflow
     8	);
     9	
    10	    parameter ALU_ADD  = 4'b0001;
    11	    parameter ALU_SUB  = 4'b0010;
    12	    parameter ALU_AND  = 4'b0011;
    13	    parameter ALU_OR   = 4'b0100;
    14	    parameter ALU_XOR  = 4'b0101;
    15	    parameter ALU_SLL  = 4'b0110;
    16	    parameter ALU_SRL  = 4'b0111;
    17	    parameter ALU_SLT  = 4'b1000;
    18	    parameter ALU_SLTU = 4'b1001;
    19	    parameter ALU_SRA  = 4'b1010;
    20	    parameter ALU_Ap4  = 4'b1011;
    21	    parameter ALU_Bout = 4'b1100;
    22	
    23	    // TODO: implement — compute the ALU result, zero flag, and overflow flag
    24	    // The ALU must support: ADD, SUB, AND, OR, XOR, SLL, SRL, SLT, SLTU, SRA, A+4, B-passthrough
    25	    // Use the Control input to select which operation to perform.
    26	    // zero should be 1 when res is all zeros.
    27	    // overflow should be set for signed ADD/SUB overflow.
    28	    assign res = 32'b0;
    29	    assign zero = 1'b0;
    30	    assign overflow = 1'b0;
    31	
    32	endmodule=========== core/ImmGen.v ===========
     1	`timescale 1ns / 1ps
     2	
     3	module ImmGen(
     4	            input  wire [2:0] ImmSel,
     5	            input  wire [31:0] inst_field,
     6	            output[31:0] Imm_out
     7	    );
     8	    parameter Imm_type_I = 3'b001;
     9	    parameter Imm_type_B = 3'b010;
    10	    parameter Imm_type_J = 3'b011;
    11	    parameter Imm_type_S = 3'b100;
    12	    parameter Imm_type_U = 3'b101;
    13	
    14	    // TODO: implement — generate the sign-extended immediate value based on ImmSel
    15	    // Must handle I-type, B-type, J-type, S-type, and U-type immediate formats
    16	    // following the RISC-V encoding specification.
    17	    assign Imm_out = 32'b0;
    18	endmodule
=========== common/cmp_32.v ===========
     1	`timescale 1ns / 1ps
     2	
     3	module cmp_32(  input [31:0] a,
     4	                input [31:0] b,
     5	                input [2:0] ctrl,
     6	                output c
     7	    );
     8	    parameter cmp_EQ  = 3'b001;
     9	    parameter cmp_NE  = 3'b010;
    10	    parameter cmp_LT  = 3'b011;
    11	    parameter cmp_LTU = 3'b100;
    12	    parameter cmp_GE  = 3'b101;
    13	    parameter cmp_GEU = 3'b110;
    14	
    15	    wire res_EQ  = a == b;
    16	    wire res_NE  = ~res_EQ;
    17	    wire res_LT  = (a[31] & ~b[31]) || (~(a[31] ^ b[31]) && a < b);
    18	    wire res_LTU = a < b;
    19	    wire res_GE  = ~res_LT;
    20	    wire res_GEU = ~res_LTU;
    21	
    22	    wire EQ  = ctrl == cmp_EQ ; 
    23	    wire NE  = ctrl == cmp_NE ; 
    24	    wire LT  = ctrl == cmp_LT ; 
    25	    wire LTU = ctrl == cmp_LTU;
    26	    wire GE  = ctrl == cmp_GE ; 
    27	    wire GEU = ctrl == cmp_GEU;
    28	
    29	    assign c = 1'b0; // TODO: implement — select correct comparison result based on ctrl
    30	
    31	endmodule=========== core/Regs.v ===========
     1	`timescale 1ns / 1ps
     2	//////////////////////////////////////////////////////////////////////////////////
     3	// Company: 
     4	// Engineer: 
     5	// 
     6	// Create Date:    21:34:44 03/12/2012 
     7	// Design Name: 
     8	// Module Name:    Regs 
     9	// Project Name: 
    10	// Target Devices: 
    11	// Tool versions: 
    12	// Description: 
    13	//
    14	// Dependencies: 
    15	//
    16	// Revision: 
    17	// Revision 0.01 - File Created
    18	// Additional Comments: 
    19	//
    20	//////////////////////////////////////////////////////////////////////////////////
    21	
    22	module     Regs(input clk,
    23					input rst,
    24					input [4:0] R_addr_A, 
    25					input [4:0] R_addr_B, 
    26					input [4:0] Wt_addr, 
    27					input [31:0]Wt_data, 
    28					input L_S, 
    29					output [31:0] rdata_A, 
    30					output [31:0] rdata_B,
    31					input [4:0] Debug_addr,         // debug address
    32					output[31:0] Debug_regs        // debug data
    33				  );
    34	
    35		reg [31:0] register [1:31]; 				// r1 - r31
    36	
    37		// TODO: implement — write-through register file
    38		// The register file must support:
    39		// - Reading two registers simultaneously (rdata_A, rdata_B) with write-through
    40		//   (if a register is being written this cycle, reads return the new value)
    41		// - Writing one register per cycle when L_S is asserted (write to Wt_addr with Wt_data)
    42		// - x0 always reads as 0
    43		// - Synchronous reset clears all registers to 0
    44		// - Debug port reads register[Debug_addr] (0 if addr is 0)
    45	
    46		assign rdata_A = 32'b0;
    47		assign rdata_B = 32'b0;
    48		assign Debug_regs = 32'b0;
    49	
    50	endmodule
    51	
    52

