// hazard_optype: 2'b00 no register write, 2'b01 ALU-like write, 2'b10 load write.
// The optype is pipelined alongside ID/EX and EX/MEM so that we know whether the
// instruction currently in EX / MEM really writes back a register (rd_EXE / rd_MEM
// are latched unconditionally and are meaningless for stores and branches).
reg[1:0] optype_EXE, optype_MEM;

initial begin
    optype_EXE = 2'b00;
    optype_MEM = 2'b00;
end

wire EXE_write = optype_EXE != 2'b00;
wire MEM_write = optype_MEM != 2'b00;

// data hazard with the instruction in EX: its result is not available yet
// (forwarding is done in ID from the MEM stage), so the ID stage must wait.
wire rs1_hazard_EXE = rs1use_ID & (rs1_ID != 5'b0) & (rs1_ID == rd_EXE);
wire rs2_hazard_EXE = rs2use_ID & (rs2_ID != 5'b0) & (rs2_ID == rd_EXE);
wire stall = EXE_write & (rs1_hazard_EXE | rs2_hazard_EXE);

always @(posedge clk) begin
    if (reg_DE_EN) optype_EXE <= reg_DE_flush ? 2'b00 : hazard_optype_ID;
    if (reg_EM_EN) optype_MEM <= optype_EXE;
end

assign PC_EN_IF     = ~stall;
assign reg_FD_EN    = 1'b1;
assign reg_FD_stall = stall;
assign reg_FD_flush = Branch_ID & ~stall;
assign reg_DE_EN    = 1'b1;
assign reg_DE_flush = stall;
assign reg_EM_EN    = 1'b1;
assign reg_EM_flush = 1'b0;
assign reg_MW_EN    = 1'b1;

// forwarding from the MEM stage back into ID (register file read port muxes)
wire forward_A = MEM_write & rs1use_ID & (rs1_ID != 5'b0) & (rs1_ID == rd_MEM);
wire forward_B = MEM_write & rs2use_ID & (rs2_ID != 5'b0) & (rs2_ID == rd_MEM);

// forwarding from the MEM stage to the store data of the instruction in EX
assign forward_ctrl_ls = MEM_write & (rs2_EXE != 5'b0) & (rs2_EXE == rd_MEM);
assign forward_ctrl_A  = forward_A ? 2'b01 : 2'b00;
assign forward_ctrl_B  = forward_B ? 2'b01 : 2'b00;

