// Self-checking testbench for lab1: replays src/lab1/all_test.s and checks the
// register write-back (PC, rd, value) sequence observed in the WB stage.
module tb_lab1;
    reg clk, rst;
    wire [31:0] debug_data;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'd0),
        .debug_data(debug_data),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0)
    );

    integer errors = 0;
    integer nwrite = 0;

    // expected (pc, rd, value) triples in retire order
    localparam NEXP = 43;
    reg [31:0] exp_pc   [0:NEXP-1];
    reg [4:0]  exp_rd   [0:NEXP-1];
    reg [31:0] exp_val  [0:NEXP-1];

    task expect_wb(input integer i, input [31:0] pc, input [4:0] rd, input [31:0] val);
        begin exp_pc[i] = pc; exp_rd[i] = rd; exp_val[i] = val; end
    endtask

    initial begin
        expect_wb( 0, 32'h004, 5'd2 , 32'h00000008);
        expect_wb( 1, 32'h008, 5'd4 , 32'h00000010);
        expect_wb( 2, 32'h00c, 5'd1 , 32'h00000018);
        expect_wb( 3, 32'h010, 5'd1 , 32'h00000017);
        expect_wb( 4, 32'h014, 5'd5 , 32'h00000014);
        expect_wb( 5, 32'h018, 5'd6 , 32'hFFFF0000);
        expect_wb( 6, 32'h01c, 5'd7 , 32'h0FFF0000);
        expect_wb( 7, 32'h020, 5'd1 , 32'h00000008);
        expect_wb( 8, 32'h024, 5'd1 , 32'h00000000);
        expect_wb( 9, 32'h028, 5'd1 , 32'h00000018);
        expect_wb(10, 32'h02c, 5'd1 , 32'h00000018);
        expect_wb(11, 32'h030, 5'd1 , 32'h00001000);
        expect_wb(12, 32'h034, 5'd1 , 32'h00000000);
        expect_wb(13, 32'h038, 5'd1 , 32'h00000001);
        expect_wb(14, 32'h03c, 5'd1 , 32'h00FFFF00);
        expect_wb(15, 32'h040, 5'd1 , 32'hFFFFFF00);
        expect_wb(16, 32'h044, 5'd1 , 32'h000FFF00);
        expect_wb(17, 32'h048, 5'd1 , 32'h00000000);
        expect_wb(18, 32'h04c, 5'd1 , 32'h00000001);
        expect_wb(19, 32'h054, 5'd1 , 32'hFFFFFFFD);
        expect_wb(20, 32'h058, 5'd1 , 32'h00000000);
        expect_wb(21, 32'h05c, 5'd1 , 32'h0000001F);
        expect_wb(22, 32'h060, 5'd1 , 32'h0000001F);
        expect_wb(23, 32'h064, 5'd1 , 32'h00000000);
        expect_wb(24, 32'h068, 5'd1 , 32'h00000020);
        expect_wb(25, 32'h06c, 5'd1 , 32'h00000004);
        expect_wb(26, 32'h070, 5'd1 , 32'hFFFFFFF0);
        expect_wb(27, 32'h074, 5'd1 , 32'h00000001);
        expect_wb(28, 32'h078, 5'd1 , 32'h00000001);
        expect_wb(29, 32'h0e8, 5'd1 , 32'h00004000);
        expect_wb(30, 32'h0ec, 5'd1 , 32'h000000F0);
        expect_wb(31, 32'h0f8, 5'd8 , 32'hFF000F0F);
        expect_wb(32, 32'h100, 5'd1 , 32'hFF000F0F);
        expect_wb(33, 32'h108, 5'd1 , 32'h00000F0F);
        expect_wb(34, 32'h110, 5'd1 , 32'h0000000F);
        expect_wb(35, 32'h114, 5'd1 , 32'hFFFFFF00);
        expect_wb(36, 32'h118, 5'd1 , 32'h0000FF00);
        expect_wb(37, 32'h11c, 5'd1 , 32'hFFFFFFFF);
        expect_wb(38, 32'h120, 5'd1 , 32'h000000FF);
        expect_wb(39, 32'h124, 5'd1 , 32'hFFFF0124);
        expect_wb(40, 32'h128, 5'd1 , 32'h0000012C);
        // program jumps back to 0 and starts over
        expect_wb(41, 32'h004, 5'd2 , 32'h00000008);
        expect_wb(42, 32'h008, 5'd4 , 32'h00000010);
    end

    initial begin
        clk = 0;
        rst = 1;
        #2 rst = 0;
    end
    always #1 clk = ~clk;

    // observe register write-backs on each rising edge of the core clock
    always @(posedge clk) begin
        if (!rst && core.RegWrite_WB && core.rd_WB != 5'd0) begin
            if (nwrite < NEXP) begin
                if (core.PC_WB !== exp_pc[nwrite] || core.rd_WB !== exp_rd[nwrite]
                        || core.wt_data_WB !== exp_val[nwrite]) begin
                    errors = errors + 1;
                    $display("MISMATCH #%0d: got pc=%h x%0d=%h, expected pc=%h x%0d=%h",
                        nwrite, core.PC_WB, core.rd_WB, core.wt_data_WB,
                        exp_pc[nwrite], exp_rd[nwrite], exp_val[nwrite]);
                end
                else begin
                    $display("ok #%0d pc=%h x%0d=%h", nwrite, core.PC_WB, core.rd_WB,
                        core.wt_data_WB);
                end
            end
            nwrite = nwrite + 1;
        end
    end

    initial begin
        #1200;
        if (nwrite < NEXP) begin
            $display("ERROR: only %0d/%0d register write-backs observed", nwrite, NEXP);
            errors = errors + 1;
        end
        // final memory state written by the store instructions
        if (core.data_ram.data[7'h1c] !== 8'h0f || core.data_ram.data[7'h1f] !== 8'hff) begin
            $display("ERROR: sw to 0x1c wrong: %h %h", core.data_ram.data[7'h1c],
                core.data_ram.data[7'h1f]);
            errors = errors + 1;
        end
        if (core.data_ram.data[7'h20] !== 8'h0f || core.data_ram.data[7'h21] !== 8'h0f) begin
            $display("ERROR: sh to 0x20 wrong");
            errors = errors + 1;
        end
        if (core.data_ram.data[7'h24] !== 8'h0f) begin
            $display("ERROR: sb to 0x24 wrong");
            errors = errors + 1;
        end
        if (errors == 0) $display("LAB1 TEST PASSED (%0d write-backs checked)", NEXP);
        else $display("LAB1 TEST FAILED with %0d errors", errors);
        $finish;
    end

endmodule

