module CSRRegs(
    input clk, rst,
    input[11:0] raddr, waddr,
    input[31:0] wdata,
    input csr_w,
    input[1:0] csr_wsc_mode,
    output[31:0] rdata,
    output[31:0] mstatus,
    // trap support: the exception unit updates mepc/mcause/mtval/mstatus at once
    input trap_w,
    input[31:0] trap_epc, trap_cause, trap_tval,
    input mret_w,
    output[31:0] mtvec, mepc
);
    // You may need to modify this module for better efficiency

    reg[31:0] CSR [0:15];

    // Address mapping. The address is 12 bits, but only 4 bits are used in this module.
    wire raddr_valid = raddr[11:7] == 5'h6 && raddr[5:3] == 3'h0;
    wire[3:0] raddr_map = (raddr[6] << 3) + raddr[2:0];
    wire waddr_valid = waddr[11:7] == 5'h6 && waddr[5:3] == 3'h0;
    wire[3:0] waddr_map = (waddr[6] << 3) + waddr[2:0];

    // 0x300 mstatus -> CSR[0], 0x304 mie -> CSR[4], 0x305 mtvec -> CSR[5],
    // 0x341 mepc -> CSR[9], 0x342 mcause -> CSR[10], 0x343 mtval -> CSR[11]
    localparam CSR_MSTATUS = 4'd0;
    localparam CSR_MTVEC   = 4'd5;
    localparam CSR_MEPC    = 4'd9;
    localparam CSR_MCAUSE  = 4'd10;
    localparam CSR_MTVAL   = 4'd11;

    localparam MODE_W = 2'b01;      // csrrw / csrrwi
    localparam MODE_S = 2'b10;      // csrrs / csrrsi
    localparam MODE_C = 2'b11;      // csrrc / csrrci

    assign mstatus = CSR[CSR_MSTATUS];
    assign mtvec   = CSR[CSR_MTVEC];
    assign mepc    = CSR[CSR_MEPC];

    assign rdata = raddr_valid ? CSR[raddr_map] : 32'b0;

    // write / set / clear
    wire[31:0] wdata_wsc = csr_wsc_mode == MODE_W ? wdata :
                           csr_wsc_mode == MODE_S ? (CSR[waddr_map] | wdata) :
                           csr_wsc_mode == MODE_C ? (CSR[waddr_map] & ~wdata) :
                                                    CSR[waddr_map];

    // mstatus fields: MIE = bit 3, MPIE = bit 7, MPP = bits 12:11
    wire[31:0] mstatus_trap = {CSR[CSR_MSTATUS][31:13], 2'b11, CSR[CSR_MSTATUS][10:8],
        CSR[CSR_MSTATUS][3], CSR[CSR_MSTATUS][6:4], 1'b0, CSR[CSR_MSTATUS][2:0]};
    wire[31:0] mstatus_mret = {CSR[CSR_MSTATUS][31:13], 2'b11, CSR[CSR_MSTATUS][10:8],
        1'b1, CSR[CSR_MSTATUS][6:4], CSR[CSR_MSTATUS][7], CSR[CSR_MSTATUS][2:0]};

    always@(posedge clk or posedge rst) begin
        if(rst) begin
			CSR[0] <= 32'h88;
			CSR[1] <= 0;
			CSR[2] <= 0;
			CSR[3] <= 0;
			CSR[4] <= 32'hfff;
			CSR[5] <= 0;
			CSR[6] <= 0;
			CSR[7] <= 0;
			CSR[8] <= 0;
			CSR[9] <= 0;
			CSR[10] <= 0;
			CSR[11] <= 0;
			CSR[12] <= 0;
			CSR[13] <= 0;
			CSR[14] <= 0;
			CSR[15] <= 0;
		end
        else if(trap_w) begin                       // 进入异常/中断处理
            CSR[CSR_MEPC]    <= trap_epc;
            CSR[CSR_MCAUSE]  <= trap_cause;
            CSR[CSR_MTVAL]   <= trap_tval;
            CSR[CSR_MSTATUS] <= mstatus_trap;
        end
        else if(mret_w) begin                       // 从异常处理返回
            CSR[CSR_MSTATUS] <= mstatus_mret;
        end
        else if(csr_w && waddr_valid) begin         // csrrw / csrrs / csrrc
            CSR[waddr_map] <= wdata_wsc;
        end
    end
endmodule

