// Trace testbench for lab2: prints the WB stage and the CSR state so the
// exception behaviour of exp_test.s can be checked.
module tb_lab2_trace;
    reg clk, rst;
    wire [31:0] wb_pc, wb_inst, mem_addr, mem_data, debug_data;
    reg interrupter;

    RV32core core(
        .debug_en(1'b0),.debug_step(1'b0),.debug_addr(7'b0),.debug_data(debug_data),
        .clk(clk),.rst(rst),.wb_pc(wb_pc),.wb_inst(wb_inst),
        .mem_addr(mem_addr),.mem_data(mem_data),.interrupter(interrupter)
    );

    initial begin clk = 0; rst = 1; interrupter = 0; #2 rst = 0; end
    always #1 clk = ~clk;

    always @(posedge clk) if (!rst) begin
        $display("t=%0t pc=%h inst=%h fl=%b rw=%b rd=%2d data=%h | trap=%b mret=%b redir=%b/%h | mstatus=%h mepc=%h mcause=%h mtval=%h mtvec=%h",
            $time, wb_pc, wb_inst, core.isFlushed_WB, core.RegWrite_WB, core.rd_WB,
            core.wt_data_WB, core.exp_unit.trap_taken, core.exp_unit.mret_taken,
            core.redirect_mux_exp, core.PC_redirect_exp,
            core.exp_unit.csr.CSR[0], core.exp_unit.csr.CSR[9], core.exp_unit.csr.CSR[10],
            core.exp_unit.csr.CSR[11], core.exp_unit.csr.CSR[5]);
    end

    initial begin #400; $finish; end
endmodule

