`timescale 1ns / 1ps

module ExceptionUnit(
    input clk, rst,
    input csr_rw_in,
    // write/set/clear (funct bits from instruction)
    input[1:0] csr_wsc_mode_in,
    input csr_w_imm_mux,
    input[11:0] csr_rw_addr_in,
    input[31:0] csr_w_data_reg,
    input[4:0] csr_w_data_imm,
    output[31:0] csr_r_data_out,

    input interrupt,
    input illegal_inst,
    input l_access_fault,
    input s_access_fault,
    input ecall_m,

    input mret,

    // information about the instruction retiring in WB, needed for mtval
    input[31:0] inst_WB,
    input[31:0] addr_WB,

    input[31:0] epc_cur,
    input[31:0] epc_next,
    output[31:0] PC_redirect,
    output redirect_mux,

    output reg_FD_flush, reg_DE_flush, reg_EM_flush, reg_MW_flush, 
    output RegWrite_cancel,
    output MemWrite_cancel
);
    // According to the diagram, design the Exception Unit
    // You can modify any code in this file if needed!
    wire[11:0] csr_waddr;
    wire[31:0] csr_wdata;
    wire csr_w;
    wire[1:0] csr_wsc;
    wire[11:0] csr_raddr;

    wire[31:0] mstatus;
    wire[31:0] csr_rdata;
    wire[31:0] mtvec, mepc;

    // ---------------- trap detection ----------------
    // exceptions belong to the instruction retiring in WB, an interrupt is taken
    // between two instructions and only when mstatus.MIE is set
    wire exception = illegal_inst | ecall_m | l_access_fault | s_access_fault;
    wire interrupt_taken = interrupt & mstatus[3] & ~exception;
    wire trap_taken = exception | interrupt_taken;
    // a younger mret must be cancelled by an older trap
    wire mret_taken = mret & ~trap_taken;

    localparam CAUSE_ILLEGAL   = 32'd2;
    localparam CAUSE_L_FAULT   = 32'd5;
    localparam CAUSE_S_FAULT   = 32'd7;
    localparam CAUSE_ECALL_M   = 32'd11;
    localparam CAUSE_INT_EXT_M = 32'h8000000b;

    wire[31:0] trap_cause = illegal_inst    ? CAUSE_ILLEGAL :
                            ecall_m         ? CAUSE_ECALL_M :
                            l_access_fault  ? CAUSE_L_FAULT :
                            s_access_fault  ? CAUSE_S_FAULT :
                                              CAUSE_INT_EXT_M;

    // mtval: faulting instruction for an illegal instruction, faulting address for
    // an access fault, 0 otherwise
    wire[31:0] trap_tval = illegal_inst ? inst_WB :
                           (l_access_fault | s_access_fault) ? addr_WB : 32'b0;

    // for an exception mepc points at the faulting instruction, for an interrupt it
    // points at the first instruction that has not been executed yet
    wire[31:0] trap_epc = exception ? epc_cur : epc_next;

    // ---------------- CSR access ----------------
    assign csr_raddr = csr_rw_addr_in;
    assign csr_waddr = csr_rw_addr_in;
    assign csr_wsc   = csr_wsc_mode_in;
    // an explicit CSR write is cancelled when an older instruction traps
    assign csr_w     = csr_rw_in & ~trap_taken;
    assign csr_wdata = csr_w_imm_mux ? {27'b0, csr_w_data_imm} : csr_w_data_reg;

    CSRRegs csr(.clk(clk),.rst(rst),.csr_w(csr_w),.raddr(csr_raddr),.waddr(csr_waddr),
        .wdata(csr_wdata),.rdata(csr_rdata),.mstatus(mstatus),.csr_wsc_mode(csr_wsc),
        .trap_w(trap_taken),.trap_epc(trap_epc),.trap_cause(trap_cause),
        .trap_tval(trap_tval),.mret_w(mret_taken),.mtvec(mtvec),.mepc(mepc));

    assign csr_r_data_out = csr_rdata;

    // ---------------- redirect and pipeline control ----------------
    assign PC_redirect  = trap_taken ? mtvec : mepc;
    assign redirect_mux = trap_taken | mret_taken;

    // A trap is detected in WB: every younger instruction (MEM, EX, ID, IF) has to be
    // cancelled. An mret is executed in MEM, so the three younger stages are cancelled.
    assign reg_FD_flush = trap_taken | mret_taken;
    assign reg_DE_flush = trap_taken | mret_taken;
    assign reg_EM_flush = trap_taken | mret_taken;
    assign reg_MW_flush = trap_taken;

    // the faulting instruction itself must not write back, and the store sitting in
    // MEM (younger than the trapping instruction) must not touch the memory
    assign RegWrite_cancel = exception;
    assign MemWrite_cancel = trap_taken;

endmodule

endmodule

