`timescale 1ns / 1ps
// Self-checking testbench for lab2: exp_test.s exercises csrrw/csrrs/csrrc,
// ecall, an illegal instruction, load/store access faults and mret.
module tb_lab2;
    reg clk, rst;
    wire [31:0] wb_pc, wb_inst, mem_addr, mem_data, debug_data;

    RV32core core(
        .debug_en(1'b0),.debug_step(1'b0),.debug_addr(7'b0),.debug_data(debug_data),
        .clk(clk),.rst(rst),.wb_pc(wb_pc),.wb_inst(wb_inst),
        .mem_addr(mem_addr),.mem_data(mem_data),.interrupter(1'b0)
    );

    integer errors = 0;
    integer ntrap = 0;
    integer nhandler = 0;

    // expected trap state: mepc, mcause, mtval
    localparam NTRAP = 4;
    reg[31:0] exp_epc[0:NTRAP-1], exp_cause[0:NTRAP-1], exp_tval[0:NTRAP-1];

    // expected csr read-back values in the very first instructions
    integer ncsr = 0;
    localparam NCSR = 4;
    reg[31:0] exp_csr_rd[0:NCSR-1];

    initial begin
        exp_epc[0] = 32'h38; exp_cause[0] = 32'h0b;        exp_tval[0] = 32'h0;
        exp_epc[1] = 32'h40; exp_cause[1] = 32'h02;        exp_tval[1] = 32'h12;
        exp_epc[2] = 32'h4c; exp_cause[2] = 32'h05;        exp_tval[2] = 32'h80;
        exp_epc[3] = 32'h54; exp_cause[3] = 32'h07;        exp_tval[3] = 32'h80;

        exp_csr_rd[0] = 32'h00000000;   // csrrwi x1, 0x306, 16 -> old value 0
        exp_csr_rd[1] = 32'h00000010;   // csrr   x1, 0x306
        exp_csr_rd[2] = 32'h00000010;   // csrrw  x1, 0x306, x6 -> old value 0x10
        exp_csr_rd[3] = 32'hffff0000;   // csrr   x1, 0x306
    end

    task check(input[31:0] got, input[31:0] want, input[127:0] what);
        begin
            if (got !== want) begin
                errors = errors + 1;
                $display("MISMATCH %0s: got %h expected %h (t=%0t)", what, got, want, $time);
            end
        end
    endtask

    initial begin clk = 0; rst = 1; #2 rst = 0; end
    always #1 clk = ~clk;

    // CSR read-back values of the first four CSR instructions
    always @(posedge clk) if (!rst) begin
        if (core.RegWrite_WB && core.rd_WB == 5'd1 && wb_pc >= 32'h18 && wb_pc <= 32'h24
                && ncsr < NCSR) begin
            check(core.wt_data_WB, exp_csr_rd[ncsr], "csr read");
            ncsr = ncsr + 1;
        end
    end

    // each trap must program mepc / mcause / mtval / mstatus as documented
    always @(posedge clk) if (!rst) begin
        if (core.exp_unit.trap_taken) begin
            if (ntrap < NTRAP) begin
                check(core.exp_unit.trap_epc,   exp_epc[ntrap],   "mepc");
                check(core.exp_unit.trap_cause, exp_cause[ntrap], "mcause");
                check(core.exp_unit.trap_tval,  exp_tval[ntrap],  "mtval");
                check(core.PC_redirect_exp, 32'h78, "trap target");
                if (!core.redirect_mux_exp) begin
                    errors = errors + 1;
                    $display("ERROR: trap without redirect at t=%0t", $time);
                end
                $display("trap #%0d: epc=%h cause=%h tval=%h", ntrap,
                    core.exp_unit.trap_epc, core.exp_unit.trap_cause, core.exp_unit.trap_tval);
            end
            ntrap = ntrap + 1;
        end
    end

    // the handler reads mepc/mcause/mstatus/mtval/mip into x25/x27/x28/x29/x30
    always @(posedge clk) if (!rst && core.RegWrite_WB) begin
        case (core.rd_WB)
            5'd25: begin check(core.wt_data_WB, exp_epc[(nhandler)%NTRAP], "x25 mepc"); end
            5'd27: begin check(core.wt_data_WB, exp_cause[(nhandler)%NTRAP], "x27 mcause"); end
            5'd28: begin check(core.wt_data_WB, 32'h1880, "x28 mstatus"); end
            5'd29: begin check(core.wt_data_WB, exp_tval[(nhandler)%NTRAP], "x29 mtval"); end
            5'd30: begin check(core.wt_data_WB, 32'h0, "x30 mip"); nhandler = nhandler + 1; end
        endcase
    end

    initial begin
        #380;
        if (ntrap < NTRAP) begin
            $display("ERROR: only %0d/%0d traps observed", ntrap, NTRAP);
            errors = errors + 1;
        end
        if (nhandler < NTRAP) begin
            $display("ERROR: handler ran %0d/%0d times", nhandler, NTRAP);
            errors = errors + 1;
        end
        if (ncsr < NCSR) begin
            $display("ERROR: only %0d/%0d csr read-backs observed", ncsr, NCSR);
            errors = errors + 1;
        end
        if (errors == 0) $display("LAB2 TEST PASSED");
        else $display("LAB2 TEST FAILED with %0d errors", errors);
        $finish;
    end
endmodule

